<script setup lang="ts">
import { computed,reactive,ref } from "vue"; import {useRoute} from "vue-router";
import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import Tabs from "@/components/zs/Tabs.vue"; import ActivityTimeline from "@/components/crm/ActivityTimeline.vue"; import UserAvatar from "@/components/crm/UserAvatar.vue"; import StatusBadge from "@/components/zs/StatusBadge.vue"; import ZButton from "@/components/zs/ZButton.vue"; import SidePanel from "@/components/zs/SidePanel.vue"; import Field from "@/components/zs/Field.vue"; import AsyncSection from "@/components/zs/AsyncSection.vue"; import ValidationMessage from "@/components/zs/ValidationMessage.vue";
import {useCrmData} from "@/composables/useCrmData"; import {useAsyncData,useMutation} from "@/composables/useAsyncData"; import {crmRepository} from "@/services/crm/repository"; import {showToast} from "@/composables/useToast"; import {setPageMeta} from "@/lib/page-meta";
setPageMeta("Contact Profile","Contact details and engagement history.");const route=useRoute(),data=useCrmData(),id=computed(()=>String(route.params.id)),state=useAsyncData(()=>crmRepository.contact(data.activeCompanyId.value,id.value),{watch:[data.activeCompanyId,id]}),item=computed(()=>state.data.value),tab=ref("Overview"),activityOpen=ref(false);const activities=computed(()=>(data.activities.data.value??[]).filter((entry)=>entry.contactId===id.value));const activity=reactive({type:"CALL",subject:"",description:"",due_at:"",priority:"MEDIUM"});const mutation=useMutation(()=>crmRepository.createActivity(data.activeCompanyId.value,{...activity,related_type:"contact",related_id:id.value,status:"PENDING"}));async function save(){const saved=await mutation.run();if(!saved)return;activityOpen.value=false;await data.activities.refresh();showToast("Activity saved",saved.subject,"success");}
</script>
<template><AppShell><AsyncSection :loading="state.loading.value" :error="state.error.value" @retry="state.refresh"><template v-if="item"><PageHeader :title="item.name" :description="`${item.title||'Contact'} at ${item.company||'Unlinked company'}`"><template #actions><StatusBadge :status="item.status"/><ZButton @click="activityOpen=true">Log activity</ZButton></template></PageHeader><Panel><Tabs v-model="tab" :items="['Overview','Activity','Notes']"/><div v-if="tab==='Overview'" class="grid gap-6 p-5 lg:grid-cols-[auto_1fr]"><UserAvatar :name="item.name"/><dl class="grid gap-4 text-xs sm:grid-cols-2"><div v-for="[key,value] in Object.entries({Company:item.company,'Job title':item.title,Department:item.department,Email:item.email,Phone:item.phone,Mobile:item.mobile,Owner:item.owner||'Unassigned','Primary contact':item.isPrimary?'Yes':'No','Last activity':item.lastActivity||'—'})" :key="key"><dt class="label-caps">{{key}}</dt><dd class="mt-1 text-content">{{value}}</dd></div></dl></div><div v-else-if="tab==='Activity'" class="p-4"><ActivityTimeline :items="activities"/></div><div v-else class="p-5 text-sm text-content-secondary">{{item.notes||'No notes recorded.'}}</div></Panel></template></AsyncSection><SidePanel :open="activityOpen" title="Log contact activity" @close="activityOpen=false"><form class="grid gap-4" @submit.prevent="save"><label><span class="label-caps">Type</span><select v-model="activity.type" class="field mt-1.5"><option>CALL</option><option>MEETING</option><option>EMAIL</option><option>TASK</option><option>NOTE</option></select></label><Field v-model="activity.subject" label="Subject" required/><Field v-model="activity.due_at" label="Due at" type="datetime-local"/><label><span class="label-caps">Description</span><textarea v-model="activity.description" class="field mt-1.5 min-h-20"/></label><ValidationMessage :message="mutation.error.value?.message"/><ZButton type="submit">Save activity</ZButton></form></SidePanel></AppShell></template>
